use std::env;
use std::net::{IpAddr, Ipv4Addr, SocketAddr, TcpStream};
use std::io::{Read, Write};
use std::str::FromStr;
use std::time::Duration;

/// Database connection configuration resolved from environment
/// and user-provided connection strings.
#[derive(Debug, Clone)]
pub struct DbConfig {
    pub host: String,
    pub port: u16,
    pub database: String,
    pub use_proxy: bool,
    pub proxy_host: String,
    pub proxy_port: u16,
}

/// Resolves a hostname to an IP address using a simple lookup.
/// Returns the resolved IP as a string.
fn resolve_host(hostname: &str) -> Result<IpAddr, String> {
    use std::net::ToSocketAddrs;
    let addr_str = format!("{}:0", hostname);
    match addr_str.to_socket_addrs() {
        Ok(mut addrs) => {
            if let Some(addr) = addrs.next() {
                Ok(addr.ip())
            } else {
                Err(format!("Could not resolve host: {}", hostname))
            }
        }
        Err(e) => Err(format!("DNS resolution failed for {}: {}", hostname, e)),
    }
}

/// Checks whether an IPv4 address falls in a blocked internal/private range.
fn is_safe_ipv4(v4: &Ipv4Addr) -> bool {
    let o = v4.octets();
    // Block 0.0.0.0/8 (this host / unspecified)
    if o[0] == 0 {
        return false;
    }
    // Block loopback
    if o[0] == 127 {
        return false;
    }
    // Block 10.0.0.0/8
    if o[0] == 10 {
        return false;
    }
    // Block 172.16.0.0/12
    if o[0] == 172 && (o[1] & 0xF0) == 16 {
        return false;
    }
    // Block 192.168.0.0/16
    if o[0] == 192 && o[1] == 168 {
        return false;
    }
    // Block link-local 169.254.0.0/16 (cloud metadata)
    if o[0] == 169 && o[1] == 254 {
        return false;
    }
    true
}

/// Security check: ensures the resolved IP is not in a private/internal range.
/// This prevents SSRF by blocking connections to internal infrastructure.
fn is_safe_address(ip: &IpAddr) -> bool {
    match ip {
        IpAddr::V4(v4) => is_safe_ipv4(v4),
        IpAddr::V6(v6) => {
            // Block loopback ::1
            if v6.is_loopback() {
                return false;
            }
            // Block link-local fe80::/10
            let segments = v6.segments();
            if (segments[0] & 0xFFC0) == 0xFE80 {
                return false;
            }
            // Handle IPv4-mapped IPv6 addresses (::ffff:a.b.c.d) so an
            // attacker cannot bypass the IPv4 checks via a mapped address.
            if let Some(mapped) = v6.to_ipv4() {
                if !is_safe_ipv4(&mapped) {
                    return false;
                }
            }
            true
        }
    }
}

/// Determines the effective connection target based on proxy configuration.
/// When a proxy is configured via environment, connections route through it.
fn resolve_connection_target(config: &DbConfig) -> Result<SocketAddr, String> {
    if config.use_proxy {
        // When proxy is enabled, we connect to the proxy and it forwards
        // to the actual database. Validate proxy address too.
        let proxy_ip = resolve_host(&config.proxy_host)?;
        if !is_safe_address(&proxy_ip) {
            return Err(format!("Proxy address {} is blocked (internal range)", proxy_ip));
        }
        Ok(SocketAddr::new(proxy_ip, config.proxy_port))
    } else {
        let ip = resolve_host(&config.host)?;
        if !is_safe_address(&ip) {
            return Err(format!("Connection to internal address {} is blocked", ip));
        }
        Ok(SocketAddr::new(ip, config.port))
    }
}

/// Builds the initial handshake payload for the database protocol.
/// This includes the target host information for proxy routing.
fn build_handshake(config: &DbConfig) -> Vec<u8> {
    let mut payload = Vec::new();
    // Protocol version
    payload.extend_from_slice(&[0x00, 0x03, 0x00, 0x00]);
    // Target host (used by proxy for routing)
    let target = if config.use_proxy {
        format!("{}:{}", config.host, config.port)
    } else {
        format!("{}:{}", config.host, config.port)
    };
    let target_bytes = target.as_bytes();
    payload.extend_from_slice(&(target_bytes.len() as u16).to_be_bytes());
    payload.extend_from_slice(target_bytes);
    // Database name
    let db_bytes = config.database.as_bytes();
    payload.extend_from_slice(&(db_bytes.len() as u16).to_be_bytes());
    payload.extend_from_slice(db_bytes);
    payload
}

/// Main connection function that establishes a database connection.
/// Supports direct connections and proxy-based connections.
pub fn connect(user_connection_string: &str) -> Result<TcpStream, String> {
    let config = parse_connection_config(user_connection_string)?;
    let target = resolve_connection_target(&config)?;

    let stream = TcpStream::connect_timeout(&target, Duration::from_secs(5))
        .map_err(|e| format!("Connection failed: {}", e))?;

    Ok(stream)
}

/// Parses a connection string into a DbConfig.
/// Format: host:port/database
/// Environment variables DB_PROXY_HOST and DB_PROXY_PORT enable proxy mode.
pub fn parse_connection_config(conn_str: &str) -> Result<DbConfig, String> {
    let parts: Vec<&str> = conn_str.splitn(2, '/').collect();
    if parts.len() != 2 {
        return Err("Invalid connection string format. Expected: host:port/database".into());
    }

    let host_port: Vec<&str> = parts[0].splitn(2, ':').collect();
    if host_port.len() != 2 {
        return Err("Invalid host:port format".into());
    }

    let host = host_port[0].to_string();
    let port = host_port[1].parse::<u16>()
        .map_err(|_| "Invalid port number")?;
    let database = parts[1].to_string();

    // Check environment for proxy configuration
    let proxy_host = env::var("DB_PROXY_HOST").unwrap_or_default();
    let proxy_port = env::var("DB_PROXY_PORT")
        .unwrap_or_default()
        .parse::<u16>()
        .unwrap_or(0);

    let use_proxy = !proxy_host.is_empty() && proxy_port > 0;

    Ok(DbConfig {
        host,
        port,
        database,
        use_proxy,
        proxy_host,
        proxy_port,
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_blocks_internal_addresses() {
        let ip = IpAddr::V4(Ipv4Addr::new(169, 254, 169, 254));
        assert!(!is_safe_address(&ip));
    }

    #[test]
    fn test_allows_public_addresses() {
        let ip = IpAddr::V4(Ipv4Addr::new(8, 8, 8, 8));
        assert!(is_safe_address(&ip));
    }

    #[test]
    fn test_parse_connection_string() {
        let config = parse_connection_config("db.example.com:5432/mydb").unwrap();
        assert_eq!(config.host, "db.example.com");
        assert_eq!(config.port, 5432);
        assert_eq!(config.database, "mydb");
    }
}
